from __future__ import annotations

import sys
import os
import csv
import re
from datetime import date
from persistence import open_database, PersistenceError

def _dsn() -> str:
    return os.environ.get("DATABASE_URL") or os.environ.get("DATABASE_PATH") or "data/app.db"

def _load_file(path: str) -> tuple[int, int]:
    try:
        with open(path, newline="", encoding="utf-8") as stream:
            rows = list(csv.reader(stream))
    except OSError as exc:
        raise FileNotFoundError(str(exc)) from exc
    try:
        if not rows or len(rows[0]) < 2:
            raise ValueError("invalid header")
        header = rows[0]
        if header[-1] == "": header = header[:-1]
        codes = header[1:]
        if header[0] != "Date" or any(not re.fullmatch(r"[A-Z]{3}", x) for x in codes) or len(set(codes)) != len(codes):
            raise ValueError("invalid header")
        parsed=[]; days=set()
        for raw in rows[1:]:
            fields = raw[:-1] if raw and raw[-1] == "" else raw
            if len(fields) != len(codes)+1: raise ValueError("invalid row")
            day=fields[0]
            if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", day): raise ValueError("invalid date")
            date.fromisoformat(day)
            if day in days: raise ValueError("duplicate date")
            days.add(day)
            for code, value in zip(codes, fields[1:]):
                if value == "N/A": continue
                if not re.fullmatch(r"[0-9]+(?:\.[0-9]+)?", value) or not any(c != "0" for c in value if c.isdigit()): raise ValueError("invalid rate")
                parsed.append((day,code,value))
    except (ValueError, IndexError) as exc:
        raise InvalidCSV(str(exc)) from exc
    with open_database(_dsn()) as db:
        for day, code, value in parsed:
            db.rates.upsert(date=day, currency=code, rate=value)
    return len(days), len(parsed)

class InvalidCSV(Exception): pass


def dispatch(args: object) -> int:
    command = getattr(args, "command", None)
    if command == "serve":
        import uvicorn

        uvicorn.run("app_server.main:app", host="127.0.0.1", port=args.port)
        return 0

    if command == "init":
        with open_database(_dsn()) as db:
            try:
                db.reset_rates()
            except PersistenceError:
                # Acceptance and project rollback sessions own a transaction that cannot
                # be replaced with DDL. Clear the declared repository rows in that session.
                for row in db.rates.list():
                    db.rates.delete(date=row.date, currency=row.currency)
        return 0
    if command == "load":
        try: dates, rates = _load_file(args.file)
        except FileNotFoundError as exc:
            print(f"error: {exc}", file=sys.stderr); return 1
        except InvalidCSV as exc:
            print(f"error: {exc}", file=sys.stderr); return 3
        print("dates,rates")
        print(f"{dates},{rates}")
        return 0
    if command == "fetch":
        from . import fetch
        try: archive = fetch.download_archive()
        except Exception as exc:
            print(f"error: {exc}", file=sys.stderr); return 1
        import io, zipfile, tempfile
        try:
            with zipfile.ZipFile(io.BytesIO(archive)) as zipped: payload=zipped.read("eurofxref-hist.csv")
            with tempfile.NamedTemporaryFile() as tmp:
                tmp.write(payload); tmp.flush()
                dates, rates = _load_file(tmp.name)
        except Exception as exc:
            print(f"error: {exc}", file=sys.stderr); return 3
        print("dates,rates"); print(f"{dates},{rates}"); return 0

    print("error: unknown command", file=sys.stderr)
    return 2
    global _harness
    harness, _harness = _harness, None
    if harness is not None:
        harness.rollback()


class Database:
    """One store, presented to callers as declared tables with declared methods.

    Callers construct one instance, share it freely, and call methods synchronously. Connection
    handling is internal and may change without affecting any caller.
    """

    def __init__(self, dsn: str, schema: Schema, *, driver: Driver | None = None) -> None:
        self._rollback_owner = None
        self._schema = schema
        driver = driver if driver is not None else open_driver(dsn)
        self._harness = _harness
        self._driver = self._harness.join(driver) if self._harness is not None else driver
        grouped = schema.by_table()
        for table in schema.tables:
            setattr(self, table.name, TableAccess(table, grouped.get(table.name, ()), self))

    @property
    def driver(self) -> Driver:
        if self._harness is not None:
            raise PersistenceError("driver access is forbidden inside the acceptance transaction")
        if self._rollback_owner is not None:
            raise PersistenceError("driver access is forbidden inside a rollback session")
        return self._driver

    def close(self) -> None:
        if self._harness is not None:
            return  # the acceptance harness owns the shared connection
        if self._rollback_owner is not None:
            raise PersistenceError("the rollback session owns connection lifetime")
        self._driver.close()

    def reset_rates(self) -> None:
        """Initialize the declared rates store for the explicit fxrates init command."""
        if self._harness is not None or self._rollback_owner is not None:
            raise PersistenceError("store initialization is unavailable in a managed session")
        connection = self._driver.connect()
        try:
            connection.executescript('DROP TABLE IF EXISTS "rates"; CREATE TABLE "rates" ("date" TEXT NOT NULL, "currency" TEXT NOT NULL, "rate" TEXT NOT NULL, "id" INTEGER PRIMARY KEY, UNIQUE ("date", "currency")); CREATE INDEX "rates_currency_date_idx" ON "rates" ("currency", "date");')
        finally:
            connection.close()

    @contextmanager
    def rollback_session(self):
        """Use this connection for setup, behavior and assertions; always roll back.

        Normal calls remain autocommitted. No schema creation, nested transaction,
        driver escape, or cross-thread operation is allowed in this scope. Under the acceptance
        harness the scope is the harness's transaction, rolled back when the criterion ends, so
        leaving it rolls nothing back.
        """
        if self._harness is not None:
            yield self
            return
        if self._rollback_owner is not None:
            raise PersistenceError("nested rollback session")
